Object.values(ICONS).forEach(x => {
    Object.keys(x).forEach(yy => {
        try {
            let temp = icons2SVG[yy];
            if (!temp) console.error(yy)
        } catch {
            console.error('did not find ', yy);
        }
    })
})


function HistoryView(props) {
    const ctx = useContext(ChatContext).chatInfo;
    const config = useContext(ConfigContext).config;
    const visHistRef = useRef(null);
    const visHistTooltipRef = useRef(null);

    const visLineRef = useRef(null);

    const drawChart = (data) => {
        if (!data || !data.length) return;

        drawIconChart(data);
        drawLineChart(data);
    }

    const histviewMaxHeight = 300; // to avoid bad look 

    const drawIconChart = (data) => {
        let svg = d3.select(visHistRef.current);
        let parentContainer = d3.select(svg.node().parentNode);
        let width = parentContainer.node().getBoundingClientRect().width;
        let height = parentContainer.node().getBoundingClientRect().height;
        // let svgHeight = Math.min(height, histviewMaxHeight); 
        let svgHeight = 320;
        svg.attr('width', width).attr('height', svgHeight);
        svg.selectAll('*').remove();

        // define scale
        let yScale = d3.scaleBand().domain(Object.keys(ICONS).filter(key => !config.shrunkComponents.includes(key))).range([20, svgHeight - 20 - config.shrunkComponents.length * 22]);

        // Compute data
        let topData = []; // {subattr, value, attr}[]
        var prevRecord = [];
        for (const [chatIdx, record] of data.entries()) {
            for (let attr of Object.keys(record)) {
                if (config.shrunkComponents.includes(attr)) continue;
                if (attr === "uncertainty" || attr === "sycophancy") continue;
                let subAttrValuesDict = record[attr];
                console.log(`Attribute: ${attr}`)
                let subAttrValuesList = Object.keys(subAttrValuesDict).map(x => ({
                    subattr: x,
                    value: subAttrValuesDict[x],
                    attr: attr,
                    delta: (chatIdx > 0) ? subAttrValuesDict[x] - prevRecord[attr][x] : 0
                }));

                let maxSubAttrbute = _.max(subAttrValuesList, x => x.value);
                topData.push({
                    ...maxSubAttrbute,
                    chatIdx
                })
            }
            prevRecord = record;
        }

        console.log(topData)

        // Draw head
        // svg.append('g').selectAll('text.rowHead')
        //     .data(Object.keys(ICONS))
        //     .enter().append('text')
        //     .attr('class', 'rowHead trait-label')
        //     .text(d => d).attr('x', 0).attr('y', x => yScale(x))
        svg.append('g').selectAll('text.rowHead')
            .data(Object.keys(ICONS).filter(key => !config.shrunkComponents.includes(key))) // Filter out keys present in config.shrunkComponents
            .enter().append('text')
            .attr('class', 'rowHead trait-label')
            .text(d => d).attr('x', 0).attr('y', x => yScale(x) + 7)

        // Draw icons
        const iconsize = 16;
        const iconmargin = 7;
        const iconstep = iconsize + iconmargin;
        const scaleFactor = 1.5;

        let tooltip = d3.select(visHistTooltipRef.current);

        const highlightLinesByAttr = (attr) => {
            let lineSvg = d3.select(visLineRef.current);

            if (attr && attr.length) {
                // only hover corresponding elements
                lineSvg.selectAll('text.label').transition().duration(500).attr('opacity', 0);
                lineSvg.selectAll('path.line').transition().duration(500).attr('opacity', 0);
                lineSvg.selectAll('circle.dPoint').transition().duration(500).attr('opacity', 0);

                lineSvg.selectAll(`[_attr=${attr}]`).transition().duration(500).attr('opacity', 1);
            } else {
                // reset all
                lineSvg.selectAll('text.label').transition().duration(500).attr('opacity', 0);
                lineSvg.selectAll('path.line').transition().duration(500).attr('opacity', 1);
                lineSvg.selectAll('circle.dPoint').transition().duration(500).attr('opacity', 1);
            }
        }
        console.log(topData);

        const mouseover = (event, d) => {
            tooltip.style("opacity", 1);

            highlightLinesByAttr(d.attr);
        };
        const mouseleave = (event, d) => {
            tooltip.style('opacity', 0);

            highlightLinesByAttr(null);
        }
        const mousemove = (event, d) => {
            tooltip.html(`Subattribute: ${d.subattr}. Value: ${d.value.toFixed(2)}. #Chat: ${d.chatIdx}.`)
            tooltip
                .style('left', event.offsetX + "px")
                .style('top', event.offsetY + "px")
        };

        let iconG = svg.append('g').selectAll('g.histIcon').data(topData).enter()
            .append('g').attr('class', "histIcon")
            .attr('transform', x => {
                // let p = icon2Path[x.subattr].scaleFactor;
                return `translate(${80 + iconstep * x.chatIdx}, ${yScale(x.attr) - yScale.bandwidth() + 6}) scale(${scaleFactor})`
            })
        iconG.html(x => `<g>${icons2SVG[x.subattr]}</g>`)
            .each(function(d) {
                let nd = d3.select(this);
                // disable mouse events on icon svgs
                nd.select('svg').attr('pointer-events', 'none');

                // add offset Y to make <svg> centered aligned
                let svgHeight = nd.select('svg').node().getBoundingClientRect().height;
                console.log(svgHeight);
                let offsetY = (yScale.bandwidth() - svgHeight) / 2; 
                nd.select('g').attr('transform', `translate(0, ${offsetY})`)
            })

        let highlightColor = d3.scaleLinear().domain([-1, 0, 1]).range(["#900252", "#F9F9F9", "#296719"]);
        let colorOpacity = 0.5;

        // iconG.each(function(d) {
        //     d3.select(this).selectAll('path').attr('stroke', highlightColor(d.delta));
        //     // console.log(x, d3.select(this));
        // })

        iconG.append('rect')
            .attr('x', x => 0)
            .attr('y', x => 0)
            .attr('width', iconsize)
            .attr('height', yScale.bandwidth() / scaleFactor)
            .attr('fill', d => highlightColor(d.delta))
            .attr('fill-opacity', colorOpacity)
            .attr('pointer-events', 'all')
            .on("mousemove", mousemove)
            .on("mouseleave", mouseleave)
            .on("mouseover", mouseover)
            .lower(); // move to back

        // Draw a legend
        let legendWidth = 300, legendHeight = 18;
        let defs = svg.append("defs");
        let linearGradient = defs.append("linearGradient")
            .attr("id", "gradient")
            .attr("x1", "0%")
            .attr("y1", "0%")
            .attr("x2", "100%")
            .attr("y2", "0%");

        linearGradient.append("stop")
            .attr("offset", "0%")
            .attr("stop-color", highlightColor(-1));
        linearGradient.append("stop")
            .attr("offset", "50%")
            .attr("stop-color", highlightColor(0));
        linearGradient.append("stop")
            .attr("offset", "100%")
            .attr("stop-color", highlightColor(1));

        // Append a rectangle to visualize the gradient
        let legendG = svg.append('g').attr('transform', `translate(0, ${svgHeight - 20})`)
        legendG.append('text').attr('x', 0).attr('y', 0)
            .text('Background colors encode Δ of probability:')
            .attr('font-size', '12px')
        legendG.append("rect")
            .attr("x", 0)
            .attr("y", 2)
            .attr("width", legendWidth)
            .attr("height", legendHeight)
            .attr('fill-opacity', colorOpacity)
            .style("fill", "url(#gradient)")

        // Append labels
        let labels = [-1, 0, 1];
        legendG.selectAll("text.legendText")
            .data(labels)
            .enter()
            .append("text").attr('class', "legendText")
            .attr("x", (d, i) => i * legendWidth / 2)
            .attr("y", legendHeight)
            .text(d => d);
    }

    const drawLineChart = (data) => {
        let recordData = []
        for (const [chatIdx, record] of data.entries()) {
            for (let attr of Object.keys(record)) {
                if (config.shrunkComponents.includes(attr)) continue;
                let subAttrValuesDict = record[attr];
                let subAttrValuesList = Object.keys(subAttrValuesDict).filter(key => key != "unknown").map(x => ({
                    subattr: x,
                    value: subAttrValuesDict[x],
                    attr: attr,
                    chatIdx
                }));

                recordData.push(...subAttrValuesList);
            }
        }
        console.log(recordData);

        // init svg
        let svg = d3.select(visLineRef.current);
        let parentContainer = d3.select(svg.node().parentNode);
        let width = parentContainer.node().getBoundingClientRect().width;
        let height = parentContainer.node().getBoundingClientRect().height;
        let svgHeight = Math.min(height, histviewMaxHeight);
        let svgWidth = width;
        svg.attr('width', width).attr('height', svgHeight);
        svg.selectAll('*').remove();

        // define scale
        let xMinN = 5, xPadding = 40, yPadding = 20;
        let yScale = d3.scaleLinear().domain([1, 0]).range([yPadding, svgHeight - yPadding]);
        let xScale = d3.scaleLinear().domain([0, Math.max(xMinN, data.length)])
            .range([xPadding, svgWidth - xPadding]);

        let dataBySubattr = d3.group(recordData, d => d.subattr);
    
        const faceoutOpacity = 0.2;

        const highlightByAttr = (attr) => {
            svg.selectAll('path.line').attr('opacity', faceoutOpacity);
            svg.selectAll('circle.dPoint').attr('opacity', faceoutOpacity);
            svg.selectAll('text.label').attr('opacity', 0);

            if (attr && attr.length) {
                svg.selectAll(`path.line[_attr=${attr}]`).attr('opacity', 1);
                svg.selectAll(`circle.dPoint[_attr=${attr}]`).attr('opacity',1);
                svg.selectAll(`text.label[_attr=${attr}]`).attr('opacity',1);
            } else {
                svg.selectAll('path.line').attr('opacity', 1);
                svg.selectAll('circle.dPoint').attr('opacity', 1);
            }
        }

        svg.append('text').text('Change over conversations')
            .attr('x', svgWidth / 2).attr('y', 12)
            .attr('text-anchor', 'middle').attr('class', 'trait-label')

        // draw line
        let line = d3.line().x(d => xScale(d.chatIdx)).y(d => yScale(d.value))
        svg.append('g').selectAll('path.line').data(dataBySubattr).enter()
            .append('path').attr('class', 'line')
            .attr('fill', 'none').attr('stroke', '#999999').attr('stroke-opacity', 1)
            .attr('d', d => line(d[1])).attr('_attr', d => d[1][0].attr)
            .on("mouseover", (e, d) => {
                highlightByAttr(d[1][0].attr)
            })
            .on("mouseleave", (e, d) => {
                highlightByAttr('');
            })

        // draw dots
        svg.append('g').selectAll('circle').data(recordData).enter()
            .append('circle').attr('class', 'dPoint').attr('r', 2.5).attr('fill', 'none').attr('stroke', '#999')
            .attr('cx', d => xScale(d.chatIdx))
            .attr('cy', d => yScale(d.value))
            .attr('_attr', d => d.attr)
            .on("mouseover", (event, d) => highlightByAttr(d.attr))
            .on("mouseleave", highlightByAttr(null))

        // draw text
        let textG = svg.append('g')
            .selectAll('text.label').data(dataBySubattr).enter()
            .append('text').attr('class', 'label')
            .text(d => d[0])
            .attr('x', d => 5 + xScale(d[1].at(-1).chatIdx))
            .attr('y', d => yScale(d[1].at(-1).value))
            .attr('opacity', 0)
            .attr('_attr', d => d[1][0].attr)

        // draw axses
        const yAxisTicks = yScale.ticks()
            .filter(tick => Number.isInteger(tick));
        svg
            .append("g")
            .attr("transform", `translate(${xPadding},0)`)      // This controls the vertical position of the Axis
            .call(d3.axisLeft(yScale)
                .tickValues(yAxisTicks).tickSize(0)
                .tickFormat(d3.format('d')));

        const xAxisTicks = xScale.ticks()
            .filter(tick => Number.isInteger(tick));
        svg.append('g')
            .attr("transform", `translate(0,${svgHeight - yPadding})`)      // This controls the vertical position of the Axis
            .call(d3.axisBottom(xScale)
                .tickValues(xAxisTicks).tickSize(0)
                .tickFormat(d3.format('d')));
    };

    useEffect(() => {
        console.log(ctx.historyYouModel);
        console.log(config.shrunkComponents);
        drawChart(ctx.historyYouModel);

    }, [ctx.historyYouModel, config.shrunkComponents])

    return (
        <div id='historyView'>
            <div className='column-half'>
                <svg ref={visHistRef} />
                <div ref={visHistTooltipRef} className='overlay-div' />
            </div>
            <div className='column-half'>
                <svg ref={visLineRef} />
            </div>
        </div>

    );
}

export { HistoryView }